changeSet.sql:
DECLARE
    v_admin       NUMBER;
    v_user        NUMBER;
    v_t23         TIMESTAMP := SYS_EXTRACT_UTC(SYSTIMESTAMP) - INTERVAL '23' MONTH;
    v_en_ventana  NUMBER;
    v_evento      VARCHAR2(30);
    v_user_rec    NUMBER;
    v_retencion   DATE;
    v_hoy         DATE := TRUNC(SYSDATE);

    PROCEDURE sembrar_rol(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_rol d
        USING (SELECT p_code AS role_code FROM dual) s
           ON (d.role_code = s.role_code)
        WHEN NOT MATCHED THEN
            INSERT (role_code, role_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');
    END sembrar_rol;
BEGIN
    sembrar_rol('EMPLEADO', 'Empleado', 901);
    sembrar_rol('ADMINISTRADOR', 'Administrador', 903);

    INSERT INTO usuario (full_name, corporate_email, username, role_code, status, password_hash, password_algorithm)
         VALUES ('Oraculo Retencion Auditoria Admin', 'oraculo.tsk052.retencion.admin@example.invalid',
                 'oraculo.tsk052.retencion.admin', 'ADMINISTRADOR', 'ACTIVO', '$argon2id$oraculo', 'argon2id')
      RETURNING user_id INTO v_admin;

    INSERT INTO usuario (full_name, corporate_email, username, role_code, status, password_hash, password_algorithm, created_at, created_by)
         VALUES ('Oraculo Retencion Auditoria', 'oraculo.tsk052.retencion@example.invalid',
                 'oraculo.tsk052.retencion', 'EMPLEADO', 'ACTIVO', '$argon2id$oraculo', 'argon2id', v_t23, v_admin)
      RETURNING user_id INTO v_user;

    INSERT INTO auditoria_acceso (user_id, username_attempted, event_type, operation, outcome, occurred_at, ip_address, user_agent)
         VALUES (v_user, 'oraculo.tsk052.retencion', 'login_ok', 'POST /auth/login', 'OK', v_t23, '10.0.0.7', 'oraculo-tsk052');

    -- 1) sigue dentro de la ventana de retencion de 24 meses
    SELECT COUNT(*) INTO v_en_ventana
      FROM auditoria_acceso
     WHERE user_id = v_user
       AND occurred_at >= SYS_EXTRACT_UTC(SYSTIMESTAMP) - INTERVAL '24' MONTH;
    IF v_en_ventana <> 1 THEN
        RAISE_APPLICATION_ERROR(-20930, 'ORACULO AC-TRZ-04: la entrada de auditoria de hace 23 meses no esta disponible dentro de la ventana de retencion de 2 anios');
    END IF;

    -- 2) la consulta por usuario y rango de fechas (AC-TRZ-03) la devuelve integra
    SELECT event_type, user_id, retention_until
      INTO v_evento, v_user_rec, v_retencion
      FROM auditoria_acceso
     WHERE user_id = v_user
       AND occurred_at BETWEEN v_t23 - INTERVAL '1' DAY AND v_t23 + INTERVAL '1' DAY;
    IF v_evento <> 'login_ok' OR v_user_rec <> v_user THEN
        RAISE_APPLICATION_ERROR(-20931, 'ORACULO AC-TRZ-04: la entrada de hace 23 meses no conserva integro su evento ni su atribucion');
    END IF;

    -- 3) retention_until derivada: aun no ha vencido, queda un mes
    IF v_retencion <= v_hoy THEN
        RAISE_APPLICATION_ERROR(-20932, 'ORACULO REQ-065: retention_until de una entrada de hace 23 meses deberia seguir vigente y vale ' || TO_CHAR(v_retencion, 'YYYY-MM-DD'));
    END IF;

    ROLLBACK;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END;

CREATE OR REPLACE TRIGGER trg_auditoria_acceso_servidor
BEFORE INSERT ON auditoria_acceso
FOR EACH ROW
BEGIN
    :NEW.occurred_at := SYS_EXTRACT_UTC(SYSTIMESTAMP);
END;

CREATE OR REPLACE TRIGGER trg_auditoria_acceso_inmutable
BEFORE UPDATE OR DELETE ON auditoria_acceso
BEGIN
    RAISE_APPLICATION_ERROR(-20003, 'El registro de auditoria de acceso es inmutable');
END;

DECLARE
    v_admin     NUMBER;
    v_user      NUMBER;
    v_falsa     TIMESTAMP := TIMESTAMP '1999-01-01 00:00:00';
    v_marca     CONSTANT VARCHAR2(150) := 'oraculo.tsk052.eventos';
    v_filas     NUMBER;
    v_tipos     NUMBER;
    v_cliente   NUMBER;
    v_servidor  NUMBER;
    v_sin_user  NUMBER;
    v_sin_id    NUMBER;
    v_falta     VARCHAR2(400);

    PROCEDURE sembrar_rol(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_rol d
        USING (SELECT p_code AS role_code FROM dual) s
           ON (d.role_code = s.role_code)
        WHEN NOT MATCHED THEN
            INSERT (role_code, role_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');
    END sembrar_rol;
BEGIN
    sembrar_rol('EMPLEADO', 'Empleado', 901);
    sembrar_rol('ADMINISTRADOR', 'Administrador', 903);

    INSERT INTO usuario (full_name, corporate_email, username, role_code, status, password_hash, password_algorithm)
         VALUES ('Oraculo Eventos Auditoria Admin', 'oraculo.tsk052.eventos.admin@example.invalid',
                 'oraculo.tsk052.eventos.admin', 'ADMINISTRADOR', 'ACTIVO', '$argon2id$oraculo', 'argon2id')
      RETURNING user_id INTO v_admin;

    INSERT INTO usuario (full_name, corporate_email, username, role_code, status, password_hash, password_algorithm, created_by)
         VALUES ('Oraculo Eventos Auditoria', 'oraculo.tsk052.eventos@example.invalid',
                 'oraculo.tsk052.eventos', 'EMPLEADO', 'ACTIVO', '$argon2id$oraculo', 'argon2id', v_admin)
      RETURNING user_id INTO v_user;

    -- Los cinco eventos del catalogo. Todos envian la marca de cliente falsa en occurred_at.
    INSERT INTO auditoria_acceso (user_id, username_attempted, event_type, operation, outcome, occurred_at, ip_address, user_agent, session_id)
         VALUES (v_user, v_marca, 'login_ok', 'POST /auth/login', 'OK', v_falsa, '10.0.0.7', 'oraculo-tsk052', 'd3f1c0de-0000-4000-8000-000000000001');
    INSERT INTO auditoria_acceso (user_id, username_attempted, event_type, operation, outcome, occurred_at, ip_address, user_agent)
         VALUES (NULL, v_marca, 'login_failed', 'POST /auth/login', 'DENIED_401', v_falsa, '10.0.0.7', 'oraculo-tsk052');
    INSERT INTO auditoria_acceso (user_id, username_attempted, event_type, operation, outcome, occurred_at, ip_address, user_agent)
         VALUES (v_user, v_marca, 'account_locked', 'POST /auth/login', 'DENIED_401', v_falsa, '10.0.0.7', 'oraculo-tsk052');
    INSERT INTO auditoria_acceso (user_id, username_attempted, event_type, operation, outcome, occurred_at, ip_address, user_agent, session_id)
         VALUES (v_user, v_marca, 'logout', 'POST /auth/logout', 'OK', v_falsa, '10.0.0.7', 'oraculo-tsk052', 'd3f1c0de-0000-4000-8000-000000000001');
    INSERT INTO auditoria_acceso (user_id, username_attempted, event_type, operation, outcome, occurred_at, ip_address, user_agent)
         VALUES (v_user, v_marca, 'permission_denied', 'GET /api/audit-log', 'DENIED_403', v_falsa, '10.0.0.7', 'oraculo-tsk052');

    -- 1) una fila por evento y los cinco tipos del catalogo presentes
    SELECT COUNT(*), COUNT(DISTINCT event_type) INTO v_filas, v_tipos
      FROM auditoria_acceso
     WHERE username_attempted = v_marca;
    IF v_filas <> 5 OR v_tipos <> 5 THEN
        RAISE_APPLICATION_ERROR(-20940, 'ORACULO AC-TRZ-02: se esperaban 5 entradas de 5 tipos distintos y hay ' || v_filas || ' entradas de ' || v_tipos || ' tipos');
    END IF;

    -- 2) estan exactamente los cinco tipos esperados
    SELECT LISTAGG(t.tipo, ',') WITHIN GROUP (ORDER BY t.tipo) INTO v_falta
      FROM (SELECT 'login_ok' AS tipo FROM dual
            UNION ALL SELECT 'login_failed' FROM dual
            UNION ALL SELECT 'account_locked' FROM dual
            UNION ALL SELECT 'logout' FROM dual
            UNION ALL SELECT 'permission_denied' FROM dual) t
     WHERE NOT EXISTS (SELECT 1
                         FROM auditoria_acceso a
                        WHERE a.username_attempted = v_marca
                          AND a.event_type = t.tipo);
    IF v_falta IS NOT NULL THEN
        RAISE_APPLICATION_ERROR(-20941, 'ORACULO AC-TRZ-02: faltan entradas de auditoria para los eventos ' || v_falta);
    END IF;

    -- 3) occurred_at lo sella el SERVIDOR: la marca del cliente se ha ignorado
    SELECT COUNT(*) INTO v_cliente
      FROM auditoria_acceso
     WHERE username_attempted = v_marca
       AND occurred_at = v_falsa;
    IF v_cliente <> 0 THEN
        RAISE_APPLICATION_ERROR(-20942, 'ORACULO REQ-061: ' || v_cliente || ' entradas conservan la marca temporal enviada por el cliente en lugar de la del servidor');
    END IF;

    SELECT COUNT(*) INTO v_servidor
      FROM auditoria_acceso
     WHERE username_attempted = v_marca
       AND occurred_at BETWEEN SYS_EXTRACT_UTC(SYSTIMESTAMP) - INTERVAL '1' HOUR
                           AND SYS_EXTRACT_UTC(SYSTIMESTAMP) + INTERVAL '1' MINUTE;
    IF v_servidor <> 5 THEN
        RAISE_APPLICATION_ERROR(-20943, 'ORACULO REQ-061: solo ' || v_servidor || ' de 5 entradas llevan occurred_at fijado por el servidor');
    END IF;

    -- 4) user_id solo es nulo en login_failed
    SELECT COUNT(*) INTO v_sin_user
      FROM auditoria_acceso
     WHERE username_attempted = v_marca
       AND user_id IS NULL
       AND event_type <> 'login_failed';
    IF v_sin_user <> 0 THEN
        RAISE_APPLICATION_ERROR(-20944, 'ORACULO REQ-061: hay ' || v_sin_user || ' entradas sin atribucion de usuario fuera de login_failed');
    END IF;

    -- 5) toda entrada recibe su identificador uuid por defecto
    SELECT COUNT(*) INTO v_sin_id
      FROM auditoria_acceso
     WHERE username_attempted = v_marca
       AND (audit_id IS NULL OR LENGTH(audit_id) <> 36);
    IF v_sin_id <> 0 THEN
        RAISE_APPLICATION_ERROR(-20945, 'ORACULO T.5 ARC-117: hay ' || v_sin_id || ' entradas sin audit_id uuid');
    END IF;

    ROLLBACK;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END;

DECLARE
    v_admin     NUMBER;
    v_user      NUMBER;
    v_audit     VARCHAR2(36);
    v_antes     VARCHAR2(4000);
    v_despues   VARCHAR2(4000);
    v_sqlcode   NUMBER;
    v_filas     NUMBER;

    PROCEDURE sembrar_rol(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_rol d
        USING (SELECT p_code AS role_code FROM dual) s
           ON (d.role_code = s.role_code)
        WHEN NOT MATCHED THEN
            INSERT (role_code, role_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');
    END sembrar_rol;

    FUNCTION instantanea(p_audit_id VARCHAR2) RETURN VARCHAR2 IS
        v_txt VARCHAR2(4000);
    BEGIN
        SELECT audit_id || '|' ||
               NVL(TO_CHAR(user_id), '~') || '|' ||
               NVL(username_attempted, '~') || '|' ||
               event_type || '|' ||
               NVL(operation, '~') || '|' ||
               outcome || '|' ||
               TO_CHAR(occurred_at, 'YYYY-MM-DD HH24:MI:SS.FF6') || '|' ||
               NVL(ip_address, '~') || '|' ||
               NVL(user_agent, '~') || '|' ||
               NVL(session_id, '~') || '|' ||
               TO_CHAR(retention_until, 'YYYY-MM-DD')
          INTO v_txt
          FROM auditoria_acceso
         WHERE audit_id = p_audit_id;
        RETURN v_txt;
    END instantanea;
BEGIN
    sembrar_rol('EMPLEADO', 'Empleado', 901);
    sembrar_rol('ADMINISTRADOR', 'Administrador', 903);

    INSERT INTO usuario (full_name, corporate_email, username, role_code, status, password_hash, password_algorithm)
         VALUES ('Oraculo Inmutable Auditoria Admin', 'oraculo.tsk052.inmutable.admin@example.invalid',
                 'oraculo.tsk052.inmutable.admin', 'ADMINISTRADOR', 'ACTIVO', '$argon2id$oraculo', 'argon2id')
      RETURNING user_id INTO v_admin;

    INSERT INTO usuario (full_name, corporate_email, username, role_code, status, password_hash, password_algorithm, created_by)
         VALUES ('Oraculo Inmutable Auditoria', 'oraculo.tsk052.inmutable@example.invalid',
                 'oraculo.tsk052.inmutable', 'EMPLEADO', 'ACTIVO', '$argon2id$oraculo', 'argon2id', v_admin)
      RETURNING user_id INTO v_user;

    INSERT INTO auditoria_acceso (user_id, username_attempted, event_type, operation, outcome, ip_address, user_agent, session_id)
         VALUES (v_user, 'oraculo.tsk052.inmutable', 'permission_denied', 'GET /api/audit-log', 'DENIED_403',
                 '10.0.0.7', 'oraculo-tsk052', 'd3f1c0de-0000-4000-8000-000000000002')
      RETURNING audit_id INTO v_audit;

    v_antes := instantanea(v_audit);

    -- 1) el UPDATE es rechazado con ORA-20003
    BEGIN
        UPDATE auditoria_acceso SET outcome = 'OK' WHERE audit_id = v_audit;
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    IF v_sqlcode <> -20003 THEN
        RAISE_APPLICATION_ERROR(-20950, 'ORACULO AC-TRZ-02: el UPDATE sobre auditoria_acceso devolvio ' || v_sqlcode || ' en lugar de ORA-20003');
    END IF;

    -- 2) el DELETE es rechazado con ORA-20003
    BEGIN
        DELETE FROM auditoria_acceso WHERE audit_id = v_audit;
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    IF v_sqlcode <> -20003 THEN
        RAISE_APPLICATION_ERROR(-20951, 'ORACULO AC-TRZ-02: el DELETE sobre auditoria_acceso devolvio ' || v_sqlcode || ' en lugar de ORA-20003');
    END IF;

    -- 3) la entrada sigue ahi e identica byte a byte
    SELECT COUNT(*) INTO v_filas FROM auditoria_acceso WHERE audit_id = v_audit;
    IF v_filas <> 1 THEN
        RAISE_APPLICATION_ERROR(-20952, 'ORACULO AC-TRZ-02: la entrada de auditoria ha desaparecido tras el intento de borrado');
    END IF;

    v_despues := instantanea(v_audit);
    IF v_antes <> v_despues
       OR RAWTOHEX(STANDARD_HASH(v_antes, 'SHA256')) <> RAWTOHEX(STANDARD_HASH(v_despues, 'SHA256')) THEN
        RAISE_APPLICATION_ERROR(-20953, 'ORACULO AC-TRZ-02: la entrada de auditoria no es identica byte a byte tras el UPDATE y el DELETE rechazados');
    END IF;

    -- 4) un tipo de evento fuera del catalogo cerrado es rechazado
    BEGIN
        INSERT INTO auditoria_acceso (user_id, username_attempted, event_type, outcome)
             VALUES (v_user, 'oraculo.tsk052.inmutable', 'password_sniffed', 'OK');
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    IF v_sqlcode <> -2290 THEN
        RAISE_APPLICATION_ERROR(-20954, 'ORACULO REQ-061: un event_type fuera del catalogo devolvio ' || v_sqlcode || ' en lugar de ORA-02290');
    END IF;

    -- 5) solo login_failed admite entrada sin usuario atribuido
    BEGIN
        INSERT INTO auditoria_acceso (user_id, username_attempted, event_type, outcome)
             VALUES (NULL, 'oraculo.tsk052.inmutable', 'login_ok', 'OK');
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    IF v_sqlcode <> -2290 THEN
        RAISE_APPLICATION_ERROR(-20955, 'ORACULO REQ-061: un login_ok sin user_id devolvio ' || v_sqlcode || ' en lugar de ORA-02290');
    END IF;

    ROLLBACK;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END;
